 def luminance(color):
  values=[int(color[i:i+2],16)/255 for i in [1,3,5]];v=[x/12.92 if x<=.04045 else ((x+.055)/1.055)**2.4 for x in values];return .2126*v[0]+.7152*v[1]+.0722*v[2]
