 p=subprocess.run(command,capture_output=True,text=True,timeout=75);(OUT/'browser.stdout').write_text(p.stdout);(OUT/'browser.stderr').write_text(p.stderr);report['browser']={'command':command,'exitCode':p.returncode,'served':served}
